USE `Cap-Central`;

-- Safely allow both legacy and new categories before migrating old records.
-- Keeping 'Trucker Hats' temporarily prevents existing rows from being truncated.
ALTER TABLE products MODIFY category ENUM('Caps','Shoes','Hats','Thobes','Trucker Hats') NOT NULL DEFAULT 'Shoes';

-- Move legacy trucker-hat products into the new Hats category.
UPDATE products
SET category = 'Hats'
WHERE category = 'Trucker Hats'
   OR product_code LIKE 'TRUCKER-WEB-%';

-- Keep only the four categories used by the admin dashboard.
ALTER TABLE products MODIFY category ENUM('Caps','Shoes','Hats','Thobes') NOT NULL DEFAULT 'Shoes';


